const fs = require('fs');

const path = 'components/chat/ChatInterface.tsx';
let content = fs.readFileSync(path, 'utf8');

// The reviewer noted: "the gift_received broadcast payload generated by handleGiftSent omits the roomId"
content = content.replace(
  /payload: \{ messageId: newMessage\.id, gift_type: giftData, senderId: currentUserProfile\?\.id, senderName: currentUserProfile\?\.name, senderAvatar: currentUserProfile\?\.avatarUrl, receiverId: currentOtherUserProfile\?\.id \}/g,
  "payload: { messageId: newMessage.id, gift_type: giftData, senderId: currentUserProfile?.id, senderName: currentUserProfile?.name, senderAvatar: currentUserProfile?.avatarUrl, receiverId: (currentOtherUserProfile as any).isGroup ? null : currentOtherUserProfile?.id, roomId: (currentOtherUserProfile as any).isGroup ? currentOtherUserProfile?.id : undefined }"
);

fs.writeFileSync(path, content);
console.log("Fixed ChatInterface.tsx payload");
